using System.Threading.Tasks;

namespace StatsOnline.Web.Controllers
{
    /// <summary>
    /// 
    /// </summary>
    /// <seealso cref="StatsOnline.Web.Controllers.BaseApiController" />
    [Authorize]
    public class VariableApiController : BaseApiController
    {
        /// <summary>
        /// The cache lock (to ensure the method to fill in the Variable's cache is only once called for multiple concurrent requests).
        /// </summary>
        private static readonly object CacheLock = new object();

        /// <summary>
        /// The maximum count of variable search results.
        /// </summary>
        private const int VariableSearchResultsLimit = 50;

        /// <summary>
        /// Gets the custom variable service.
        /// </summary>
        protected ICustomVariableService CustomVariableService { get; } = IocResolver.Resolve<ICustomVariableService>();

        /// <summary>
        /// Gets the category tree.
        /// </summary>
        [HttpGet]
        public IList<TreeNode> GetCategoryTree(bool benchmarking = false, bool excludeCustomVariables = false)
        {
            UserDto user = CurrentUserDto;
            List<SurveyCategoryDto> categories = benchmarking
                ? SessionWrapper.GetUserSurveyCategoriesForBenchmarkingAccess
                : SessionWrapper.AllSurveyCategoriesWithAccess();

            IList<TreeNode> categoryNodes = categories.ConvertAll(TreeNodeFactory.FromSurveyCategory);

            if (!excludeCustomVariables)
            {
                categoryNodes.Add(TreeNodeFactory.FromCustomVariableCategory());
            }

            return categoryNodes;
        }

        /// <summary>
        /// Gets the variables for specified subcategory.
        /// </summary>
        /// <param name="subCategoryId">The sub category identifier.</param>
        [HttpGet]
        public IList<TreeNode> GetVariables(int subCategoryId, bool onlyNumeric = false, bool benchmarking = false)
        {
            UserDto user = CurrentUserDto;
            int collectionId = SessionWrapper.LastClosedCollectionId;
            bool includeVariableId = !benchmarking || user.IsNAISStaffUser;

            if (subCategoryId == Constants.CustomVariableCategory)
            {
                return SurveyService.GetCustomVariables(user).Payload
                    .Select(cv => TreeNodeFactory.FromVariable(cv, includeVariableId))
                    .ToArray();
            }
            else
            {
                PayloadResponse<List<VariableDto>> variablesResponse = onlyNumeric
                    ? SurveyService.GetNumericVariableDtosForSubcategory(subCategoryId, user)
                    : SurveyService.GetReportingVariablesForSubCategory(subCategoryId, collectionId, user);

                List<VariableDto> variables = variablesResponse.Payload
                    .OrderBy(var => var.AssociationGroupId == Constants.NAISAssociationGroupId ? 0 : var.AssociationGroupId)
                    .ThenBy(var => var.SortOrder)
                    .ToList();

                // We have to create the intermediate node level by the group label, so we group them by GroupLabelNum
                return variables.GroupBy(v => v.GroupLabelNum)
                    .Select(group =>
                    {
                        var firstGroupVariable = group.First();
                        var groupLabel = firstGroupVariable.GroupLabel.NullIfEmpty() ?? "[ Undefined Group ]"; // TODO:NIKOS: Any reason that a couple of group labels are empty?

                        return new TreeCategoryNode
                        {
                            Id = $"g:{subCategoryId}:{group.Key}",
                            Text = new[] { firstGroupVariable.AssociationName, groupLabel }.SmartJoin(" - "),
                            Type = VariableTreeNodeType.Group.ToString(),
                            HasChildren = true,
                            HasPriorityVariables = group.Any(v => v.IsPriority),
                            Items = group.Select(v => TreeNodeFactory.FromVariable(v, includeVariableId)).ToArray()
                        };
                    })
                    .ToArray();
            }
        }

        /// <summary>
        /// Gets the filter model.
        /// </summary>
        [HttpGet]
        public FilterModel GetFilterModel()
        {
            FilterModel filterModel = new FilterModel
            {
                FilterOperatorAvailabities = HelperExtensions.GetEnumValueInfos<FilterOperatorAvailability>(),
                GroupOperators = HelperExtensions.GetEnumValueInfos<GroupOperator>(),
                FilterOperators = FilterOperatorInfo.GetOperators()
            };

            return filterModel;
        }

        /// <summary>
        /// Gets the school filter model.
        /// </summary>
        [HttpGet]
        public FilterModel GetSchoolFilterModel()
        {
            IStatisticalTablesService statisticalTablesService = new StatisticalTablesService();
            StatisticalTablesLookupDto schoolLookUps = statisticalTablesService.GetLookupData();
            UserDto user = CurrentUserDto;

            FilterModel filterModel = new FilterModel
            {
                FilterOperatorAvailabities = HelperExtensions.GetEnumValueInfos<FilterOperatorAvailability>(),
                GroupOperators = HelperExtensions.GetEnumValueInfos<GroupOperator>(),
                FilterOperators = FilterOperatorInfo.GetOperators(),
                SchoolFilterVariables = SchoolFilterVariableInfo.GetSchoolFilterVariables(schoolLookUps, user),
                IsStaffUser = CurrentUserDto.IsNAISStaffUser
            };

            return filterModel;
        }

        [HttpPost]
        public void SaveFilterTree(FilterExpressionTree filterExpressionTree)
        {
            // TODO: To be removed -always saved as part of a parent object.
        }

        /// <summary>
        /// Searches the variables.
        /// </summary>
        /// <param name="searchTerm">The search term.</param>
        /// <param name="excludeVarIds">A comma separated value with the variable ids which should be excluded from the search results.</param>
        /// <param name="onlyNumeric">if set to <c>true</c> only numeric variables will be returned (defaults to false).</param>
        /// <param name="excludeCustomVariables">if set to <c>true</c> custom variables will be excluded from the search results (defaults to false).</param>
        /// <param name="benchmarking">
        /// If set to <c>true</c> returns the VariableId in results only for Staff users, otherwise the VarId is included in the variable name.
        /// Note: When the VariableId is omitted, it will not be matched by the search term as well.
        /// </param>
        /// <returns></returns>
        [HttpGet]
        public VariableSearchResult SearchVariables(string searchTerm,
            string excludeVarIds = null,
            bool onlyNumeric = false,
            bool excludeCustomVariables = false,
            bool benchmarking = false,
            bool onlyPriority = false)
        {
            if (string.IsNullOrWhiteSpace(searchTerm) || searchTerm.Trim().Length < 3)
                return VariableSearchResult.Empty(searchTerm);

            IList<int> excludedVariableIds = string.IsNullOrEmpty(excludeVarIds)
                ? new int[0]
                : excludeVarIds.Split(',').Select(s => int.Parse(s)).ToArray();

            UserDto user = CurrentUserDto;
            int collectionId = SessionWrapper.LastClosedCollectionId;
            IList<VariableDto> variables = GetReportingVariables(user, collectionId);

            List<SurveyCategoryDto> categories = benchmarking
                ? SessionWrapper.GetUserSurveyCategoriesForBenchmarkingAccess
                : SessionWrapper.AllSurveyCategories;

            HashSet<int> allowedSubcategories = new HashSet<int>(categories.SelectMany(c => c.SubCategories).Select(sc => sc.Id));
            allowedSubcategories.Add(Constants.CustomVariableCategory);

            IEnumerable<VariableDto> filteredVariables = variables
                // Exclude specified VarIds
                .Where(v => !excludedVariableIds.Contains(v.VarId))
                // Exclude non-numeric variables when requested (onlyNumeric: true)
                .Where(v => !onlyNumeric || v.IsNumeric == true)
                // Exclude non-priority variables when requested (onlyPriority: true)
                .Where(v => !onlyPriority || v.IsPriority == true)
                // Exclude custom variables when requested (excludeCustomVariables: true)
                .Where(v => !excludeCustomVariables || v.SubCategory != Constants.CustomVariableCategory)
                // Exclude variables for subcategories the user does not have access to
                .Where(v => allowedSubcategories.Contains(v.SubCategory));

            bool includeVariableIdInName = !benchmarking || user.IsNAISStaffUser;
            VariableNameSearchHelper variableSearchHelper = new VariableNameSearchHelper(searchTerm, includeVariableIdInName);

            IEnumerable<VariableDto> matchedVariables = variableSearchHelper.GetMatches(filteredVariables)
                .ThenBy(var => var.AssociationGroupId == Constants.NAISAssociationGroupId ? 0 : var.AssociationGroupId)
                .ThenBy(var => var.SortOrder);

            int totalCount = matchedVariables.Count();
            IList<VariableSearchResultItem> items = matchedVariables.Take(VariableSearchResultsLimit).Select(v => new VariableSearchResultItem
            {
                Id = v.VarId,
                Text = variableSearchHelper.GetHighlightedName(v),
                Var = v
            }).ToList();

            return VariableSearchResult.Create(searchTerm, totalCount, items);
        }       

        /// <summary>
        /// Gets the question options for a variable.
        /// </summary>
        /// <param name="varId">The variable identifier.</param>
        /// <returns></returns>
        /// <exception cref="System.Web.Http.HttpResponseException"></exception>
        [HttpGet]
        public IList<OptionDto> GetQuestionOptions(int varId)
        {
            OptionListResponse optionListReponse = SurveyService.GetQuestionLookupGroupValues(varId);
            if (optionListReponse.ResultCode == ResponseResultCode.Success)
                return optionListReponse.Options;

            HttpResponseMessage responseMessage = new HttpResponseMessage(HttpStatusCode.InternalServerError)
            {
                Content = new StringContent($"Error Code: {optionListReponse.ResultCode} - error(s) occured: ({string.Join(", ", optionListReponse.Errors)})")
            };

            throw new HttpResponseException(responseMessage);
        }
        
        /// <summary>
        /// Gets the custom variable editor.
        /// </summary>
        [HttpGet]
        public CustomVariableEditorOptions GetCustomVariableEditorOptions()
        {
            IList<ShareTypeCode> userShareTypes = UserService.GetCustomVariableShareTypesForUser(CurrentUserDto);
            return new CustomVariableEditorOptions(userShareTypes);
        }

        /// <summary>
        /// Gets the custom variable.
        /// </summary>
        /// <param name="id">The identifier.</param>
        [HttpGet]
        public CustomVariableDto GetCustomVariable(int id)
        {
            PayloadResponse<CustomVariableDto> payloadResponse = CustomVariableService.GetCustomVariable(id);

            if (payloadResponse.ResultCode == ResponseResultCode.Success)
            {
                CustomVariableDto customVariable = payloadResponse.Payload;
                return customVariable;
            }

            throw new HttpResponseException(HttpStatusCode.NotFound);
        }

        /// <summary>
        /// Gets the custom variable's expression.
        /// </summary>
        /// <param name="id">The identifier.</param>
        [HttpGet]
        public VariableExpressionTree GetCustomVariableExpression(int id)
        {
            PayloadResponse<CustomVariableDto> payloadResponse = CustomVariableService.GetCustomVariable(id);
            if (payloadResponse.ResultCode == ResponseResultCode.Success)
            {
                CustomVariableDto customVariable = payloadResponse.Payload;
                return customVariable.ExpressionTree;
            }

            throw new HttpResponseException(HttpStatusCode.NotFound);
        }

        /// <summary>
        /// Saves the custom variable.
        /// </summary>
        /// <param name="customVariable">The custom variable.</param>
        /// <returns>The saved custom variable instance.</returns>
        /// <exception cref="System.Web.Http.HttpResponseException"></exception>
        [HttpPost]
        public CustomVariableDto SaveCustomVariable(CustomVariableDto customVariable)
        {
            bool isNew = customVariable.Id == Constants.NewIdentifier || customVariable.Id == default(int);
            if (isNew)
            {
                customVariable.UserId = CurrentUserDto.Id;
            }

            PayloadResponse<CustomVariableDto> payloadResponse = CustomVariableService.Update(customVariable, CurrentUserDto);
            if (payloadResponse.ResultCode == ResponseResultCode.Success)
            {
                // We invalidate the reporting variable cache (which includes Custom Variables)
                InvalidateReportingVariablesCache(CurrentUserDto);

                return payloadResponse.Payload;
            }

            HttpResponseMessage responseMessage = Request.CreateErrorResponse(HttpStatusCode.BadRequest, new HttpError(string.Join(", ", payloadResponse.Errors)));
            throw new HttpResponseException(responseMessage);
        }

        /// <summary>
        /// Ensures that the user's variable search cache is initialized -to minimize first search impact.
        /// </summary>
        /// <returns></returns>
        [HttpPost]
        public bool EnsureVariableSearchCache()
        {
            UserDto user = CurrentUserDto;
            int collectionId = SessionWrapper.LastClosedCollectionId;
            Task.Run(() => GetReportingVariables(user, collectionId));
            return true;
        }

        /// <summary>
        /// Gets the reporting variables for a specified user and collection id (temporarilly caches the result -15 minutes sliding expiration).
        /// </summary>
        /// <param name="user">The user.</param>
        /// <param name="collectionId">The collection identifier.</param>
        private IList<VariableDto> GetReportingVariables(UserDto user, int collectionId, bool onlyPriorityVariables = false)
        {
            string cacheKey = GetReportingVariablesCacheKey(user);

            object cachedVariables = HttpRuntime.Cache.Get(cacheKey);
            if (cachedVariables == null)
            {
                lock (CacheLock)
                {
                    cachedVariables = HttpRuntime.Cache.Get(cacheKey);
                    if (cachedVariables == null)
                    {
                        cachedVariables = SurveyService.GetReportingVariables(collectionId, true, user).Payload.ToArray();
                        HttpRuntime.Cache.Add(cacheKey,
                            cachedVariables,
                            null,
                            Cache.NoAbsoluteExpiration,
                            TimeSpan.FromMinutes(15d),
                            CacheItemPriority.BelowNormal,
                            null);
                    }
                }
            }

            IList<VariableDto> variables = cachedVariables as IList<VariableDto>;
            if (onlyPriorityVariables)
            {
                variables = variables.Where(v => v.IsPriority).ToList();
            }

            return variables;
        }

        /// <summary>
        /// Invalidates the report variables cache for a user.
        /// </summary>
        /// <param name="user">The user.</param>
        private void InvalidateReportingVariablesCache(UserDto user)
        {
            string cacheKey = GetReportingVariablesCacheKey(user);
            HttpRuntime.Cache.Remove(cacheKey);
        }

        /// <summary>
        /// Gets the user-based reporting variables cache key (depends on user's Id and WorkingSchoolNumber).
        /// </summary>
        /// <param name="user">The user.</param>
        private string GetReportingVariablesCacheKey(UserDto user)
        {
            return $"__ReportingVariables_u:{user.Id}_s:{user.WorkingSchoolNumber}";
        }
    }
}
